<?php declare(strict_types=1);require dirname(__DIR__,2).'/includes/bootstrap.php';require_permission('hunts.view');$id=(int)input('id');$s=db()->prepare('SELECT * FROM hunts WHERE id=?');$s->execute([$id]);$hunt=$s->fetch();if(!$hunt){http_response_code(404);exit('Hunt not found');}
if(is_post()){require_permission('hunts.manage');verify_csrf();$action=(string)input('action');try{$pdo=db();$pdo->beginTransaction();if($action==='location'){$lat=(string)input('latitude');$lon=(string)input('longitude');$radius=(int)input('radius_meters');if(!is_numeric($lat)||!is_numeric($lon)||(float)$lat < -90||(float)$lat > 90||(float)$lon < -180||(float)$lon > 180||$radius<1)throw new InvalidArgumentException('Invalid coordinates or radius.');$pdo->prepare('INSERT INTO hunt_locations(hunt_id,name,address,latitude,longitude,radius_meters,sort_order,status) VALUES(?,?,?,?,?,?,?,?)')->execute([$id,trim((string)input('name')),trim((string)input('address')),$lat,$lon,$radius,(int)input('sort_order'),'ACTIVE']);$record=(string)$pdo->lastInsertId();}
elseif($action==='qr'){$location=(int)input('location_id');$check=$pdo->prepare('SELECT id FROM hunt_locations WHERE id=? AND hunt_id=?');$check->execute([$location,$id]);if(!$check->fetch())throw new InvalidArgumentException('Invalid hunt location.');$token=bin2hex(random_bytes(32));$expires=trim((string)input('expires_at'));$expires=$expires?str_replace('T',' ',$expires):null;$max=trim((string)input('max_scans'));$pdo->prepare('INSERT INTO hunt_qr_codes(hunt_id,location_id,token_hash,label,status,expires_at,max_scans,created_by) VALUES(?,?,?, ?,"ACTIVE",?,?,?)')->execute([$id,$location,hash('sha256',$token),trim((string)input('label')),$expires,$max===''?null:(int)$max,admin()['id']]);$record=(string)$pdo->lastInsertId();$_SESSION['_qr_once']='hunter://scan?t='.$token;}
elseif($action==='video'){$url=trim((string)input('video_url'));if(!filter_var($url,FILTER_VALIDATE_URL))throw new InvalidArgumentException('A valid HTTPS video URL is required.');$pdo->prepare('INSERT INTO hunt_videos(hunt_id,location_id,title,video_url,sort_order,status) VALUES(?,?,?,?,?,"ACTIVE")')->execute([$id,(int)input('location_id')?:null,trim((string)input('title')),$url,(int)input('sort_order')]);$record=(string)$pdo->lastInsertId();}
elseif($action==='secret'){$code=trim((string)input('code'));$from=str_replace('T',' ',trim((string)input('valid_from')));$until=str_replace('T',' ',trim((string)input('valid_until')));if(strlen($code)<4||!strtotime($from)||!strtotime($until)||strtotime($until)<=strtotime($from))throw new InvalidArgumentException('Secret and validity window are required.');$pdo->prepare('INSERT INTO hunt_secret_codes(hunt_id,location_id,code_hash,valid_from,valid_until,status,created_by) VALUES(?,?,?, ?,?,"ACTIVE",?)')->execute([$id,(int)input('location_id')?:null,password_hash($code,PASSWORD_DEFAULT),$from,$until,admin()['id']]);$record=(string)$pdo->lastInsertId();}
elseif($action==='question'){$answer=trim((string)input('answer'));$type=strtoupper((string)input('question_type'));if($answer===''||!in_array($type,['TEXT','MCQ'],true))throw new InvalidArgumentException('Question and answer are required.');$pdo->prepare('INSERT INTO hunt_questions(hunt_id,location_id,question_text,question_type,correct_answer_hash,sort_order,status,created_by) VALUES(?,?,?,?,?,?,"ACTIVE",?)')->execute([$id,(int)input('location_id')?:null,trim((string)input('question_text')),$type,answer_hash($answer),(int)input('sort_order'),admin()['id']]);$qid=(int)$pdo->lastInsertId();foreach(array_filter(array_map('trim',preg_split('/\R/',(string)input('options'))?:[])) as $order=>$option)$pdo->prepare('INSERT INTO hunt_question_options(question_id,option_text,sort_order) VALUES(?,?,?)')->execute([$qid,$option,$order]);$record=(string)$qid;}
elseif($action==='toggle'){$table=(string)input('table');$allowed=['hunt_locations','hunt_qr_codes','hunt_videos','hunt_secret_codes','hunt_questions'];if(!in_array($table,$allowed,true))throw new InvalidArgumentException('Invalid module.');$record=(string)(int)input('record_id');$pdo->prepare("UPDATE {$table} SET status=IF(status='ACTIVE','INACTIVE','ACTIVE') WHERE id=? AND hunt_id=?")->execute([(int)$record,$id]);}
else throw new InvalidArgumentException('Unknown action.');audit_log((int)admin()['id'],'HUNT_'.strtoupper($action),'hunts',$record??null,null,['hunt_id'=>$id]);$pdo->commit();flash('success',$action==='qr'?'QR created. Copy the payload below now; it is not stored in plaintext.':'Hunt component saved.');}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();flash('error',$e->getMessage());}redirect('/admin/hunts/manage.php?id='.$id);}
$locations=db()->prepare('SELECT * FROM hunt_locations WHERE hunt_id=? ORDER BY sort_order,id');$locations->execute([$id]);$locations=$locations->fetchAll();$load=static function(string $table)use($id){$s=db()->prepare("SELECT * FROM {$table} WHERE hunt_id=? ORDER BY id DESC");$s->execute([$id]);return $s->fetchAll();};$qrs=$load('hunt_qr_codes');$videos=$load('hunt_videos');$secrets=$load('hunt_secret_codes');$questions=$load('hunt_questions');$once=$_SESSION['_qr_once']??null;unset($_SESSION['_qr_once']);$pageTitle='Manage '.$hunt['title'];$pageSubtitle='Locations, opaque QR tokens, videos, rotating secrets and questions';require APP_ROOT.'/includes/header.php';?>
<?php if($once):?><section class="panel one-time"><h2>One-time QR payload</h2><p class="help">Copy this now. Only its SHA-256 hash is stored.</p><input readonly value="<?=e($once)?>" aria-label="QR payload"></section><?php endif?>
<section class="panel"><h2>Locations</h2><?php if(can('hunts.manage')):?><form method="post" class="filters"><?=csrf_field()?><input type="hidden" name="action" value="location"><input name="name" placeholder="Location name" required><input name="address" placeholder="Address"><input name="latitude" placeholder="Latitude" required><input name="longitude" placeholder="Longitude" required><input name="radius_meters" type="number" min="1" value="100" required><input name="sort_order" type="number" min="0" value="0"><button class="btn">Add location</button></form><?php endif?><div class="table-wrap"><table><thead><tr><th>Name</th><th>Coordinates</th><th>Radius</th><th>Order</th><th>Status</th></tr></thead><tbody><?php foreach($locations as $l):?><tr><td><?=e($l['name'])?></td><td><?=e($l['latitude'])?>, <?=e($l['longitude'])?></td><td><?=e($l['radius_meters'])?> m</td><td><?=e($l['sort_order'])?></td><td><?=e($l['status'])?></td></tr><?php endforeach?></tbody></table></div></section>
<section class="panel"><h2>Opaque QR codes</h2><?php if(can('hunts.manage')&&$locations):?><form method="post" class="filters"><?=csrf_field()?><input type="hidden" name="action" value="qr"><select name="location_id" required><?php foreach($locations as $l):?><option value="<?=e($l['id'])?>"><?=e($l['name'])?></option><?php endforeach?></select><input name="label" placeholder="Label"><input type="datetime-local" name="expires_at"><input type="number" name="max_scans" min="1" placeholder="Optional max scans"><button class="btn">Generate QR payload</button></form><?php endif?><div class="table-wrap"><table><thead><tr><th>ID</th><th>Location</th><th>Label</th><th>Scans</th><th>Expires</th><th>Status</th></tr></thead><tbody><?php foreach($qrs as $r):?><tr><td>#<?=e($r['id'])?></td><td>#<?=e($r['location_id'])?></td><td><?=e($r['label']??'—')?></td><td><?=e($r['scan_count'])?> / <?=e($r['max_scans']??'∞')?></td><td><?=e($r['expires_at']??'Never')?></td><td><?=e($r['status'])?></td></tr><?php endforeach?></tbody></table></div></section>
<div class="grid detail-grid"><section class="panel"><h2>Videos</h2><?php if(can('hunts.manage')):?><form method="post" class="stack"><?=csrf_field()?><input type="hidden" name="action" value="video"><input name="title" placeholder="Title" required><input type="url" name="video_url" placeholder="https://…" required><select name="location_id"><option value="">Whole hunt</option><?php foreach($locations as $l):?><option value="<?=e($l['id'])?>"><?=e($l['name'])?></option><?php endforeach?></select><input type="number" name="sort_order" value="0" min="0"><button class="btn">Add video</button></form><?php endif?><?php foreach($videos as $v):?><div class="kv"><span><?=e($v['title'])?></span><strong><?=e($v['status'])?></strong></div><?php endforeach?></section>
<section class="panel"><h2>Rotating secrets</h2><?php if(can('hunts.manage')):?><form method="post" class="stack"><?=csrf_field()?><input type="hidden" name="action" value="secret"><input type="password" name="code" minlength="4" placeholder="Secret (stored hashed)" required autocomplete="new-password"><select name="location_id"><option value="">Whole hunt</option><?php foreach($locations as $l):?><option value="<?=e($l['id'])?>"><?=e($l['name'])?></option><?php endforeach?></select><input type="datetime-local" name="valid_from" required><input type="datetime-local" name="valid_until" required><button class="btn">Add secret</button></form><?php endif?><?php foreach($secrets as $v):?><div class="kv"><span>#<?=e($v['id'])?> · <?=e($v['valid_from'])?></span><strong><?=e($v['status'])?></strong></div><?php endforeach?></section></div>
<section class="panel"><h2>Questions</h2><?php if(can('hunts.manage')):?><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="question"><div class="field full"><label>Question</label><textarea name="question_text" required></textarea></div><div class="field"><label>Type</label><select name="question_type"><option>TEXT</option><option>MCQ</option></select></div><div class="field"><label>Location</label><select name="location_id"><option value="">Whole hunt</option><?php foreach($locations as $l):?><option value="<?=e($l['id'])?>"><?=e($l['name'])?></option><?php endforeach?></select></div><div class="field"><label>Correct answer</label><input type="password" name="answer" required autocomplete="new-password"><span class="help">Only a normalized hash is stored.</span></div><div class="field"><label>Options, one per line</label><textarea name="options"></textarea></div><div class="field"><label>Order</label><input type="number" name="sort_order" value="0" min="0"></div><div class="field full"><button class="btn">Add question</button></div></form><?php endif?><div class="table-wrap"><table><thead><tr><th>ID</th><th>Question</th><th>Type</th><th>Location</th><th>Order</th><th>Status</th></tr></thead><tbody><?php foreach($questions as $q):?><tr><td>#<?=e($q['id'])?></td><td><?=e($q['question_text'])?></td><td><?=e($q['question_type'])?></td><td><?=e($q['location_id']??'All')?></td><td><?=e($q['sort_order'])?></td><td><?=e($q['status'])?></td></tr><?php endforeach?></tbody></table></div></section><?php require APP_ROOT.'/includes/footer.php';
